def document(title):
 d=Document();s=d.sections[0];s.page_width=Cm(21);s.page_height=Cm(29.7);s.left_margin=Cm(3);s.right_margin=Cm(1.5);s.top_margin=s.bottom_margin=Cm(2)
 for name in ['Normal','Title','Heading 1','Heading 2','Caption']:
  st=d.styles[name];st.font.name='Times New Roman';st.font.size=Pt(14);st.font.color.rgb=RGBColor(0,0,0)
  fonts=st.element.get_or_add_rPr().get_or_add_rFonts()
  for a in ['asciiTheme','hAnsiTheme','eastAsiaTheme','cstheme']:
   if qn('w:'+a) in fonts.attrib:del fonts.attrib[qn('w:'+a)]
  for a in ['ascii','hAnsi','eastAsia','cs']:fonts.set(qn('w:'+a),'Times New Roman')
  st.paragraph_format.line_spacing=1.5;st.paragraph_format.space_after=Pt(6);st.paragraph_format.first_line_indent=Cm(1.25)
 d.styles['Normal'].paragraph_format.alignment=3
 for st in d.styles:
  for border in list(st.element.findall('.//'+qn('w:pBdr'))):border.getparent().remove(border)
 d.styles['Heading 1'].paragraph_format.page_break_before=True
 d.styles['Heading 1'].paragraph_format.keep_with_next=True
 footer=s.footer.paragraphs[0];footer.alignment=1;footer.paragraph_format.first_line_indent=Cm(0)
 f=OxmlElement('w:fldSimple');f.set(qn('w:instr'),'PAGE');footer._p.append(f)
 q=d.add_paragraph(title,'Title');q.alignment=1;q.paragraph_format.first_line_indent=Cm(0)
 d.add_paragraph('План исследовательской проверки от 23 ноября 2026 года')
 return d
def paragraph(d,text):return d.add_paragraph(text)
def heading(d,text):return d.add_heading(text,1)
def table(d,title,headers,rows,widths):
 p=d.add_paragraph(title);p.paragraph_format.keep_with_next=True;p.paragraph_format.first_line_indent=Cm(0)
 t=d.add_table(rows=1,cols=len(headers));t.autofit=False
 for c,w in zip(t.columns,widths):c.width=Cm(w)
 for cell,text in zip(t.rows[0].cells,headers):cell.text=str(text)
 t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
 for row in rows:
  for cell,text in zip(t.add_row().cells,row):cell.text=str(text)
 for row in t.rows:
  row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
  for cell in row.cells:
   for p in cell.paragraphs:
    p.alignment=0;p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.line_spacing=1.05;p.paragraph_format.space_after=Pt(4)
    for r in p.runs:r.font.size=Pt(12)
 b=OxmlElement('w:tblBorders')
 for side in ['top','left','bottom','right','insideH','insideV']:
  e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
 t._tbl.tblPr.append(b)
 return t
def plan():
 d=document('Повторная проверка воспроизводимости исторического обучения нейронов')
 paragraph(d,'Цель работы — получить новые обученные состояния, измерить их инференс и объективно установить различия с архивом и предыдущей проверкой. Совпадение структуры не является обязательным условием завершения обучения. Исторические результаты рассматриваются как наблюдения, а не как единственно правильное решение.')
 paragraph(d,'Сохраняются три независимые группы данных: исходные исторические материалы, результаты ScientificComparisons от 23.11.2026 и результаты нового обучения. Предыдущие файлы защищены контрольными суммами. Новая работа выполняется в исследовательских ветках classic-training-reproducibility от classic-structtrain-validation.')
 paragraph(d,'NT означает NNeuronTrainer, NL — NNeuronLearner. № 51 и № 61 — номера объектов Iris во втором классе. Средний вход вычисляется покомпонентно из их нормированных задержек. Длина дендрита задаётся числом сегментов, число синапсов учитывается отдельно для каждого из пяти каналов.')
 heading(d,'1 Источники и датировка')
 paragraph(d,'Основной структурный источник — «Инофрмация о длинах дендритов и числе синапсов.xlsx», лист «Дендриты и синапсы», в каталоге Docs/ClassicStructTrainExperiments/Эксперименты. Источники измеренных ответов и учебных последовательностей — протоколы, таблицы распознавания, рабочие документы, output_data и ВКР. Дубликаты публикаций не создают дополнительные независимые опыты.')
 paragraph(d,'Истории сохранений конфигураций относятся к марту 2022 года. Метаданные рабочих документов показывают сохранения весной и в июне 2022 года. Это свидетельства состояния документов, а не точные даты запуска. Даты создания некоторых XLSX в 2015 году не используются как даты опытов.')
 paragraph(d,'В доступной Git-истории NNeuronLearner впервые появляется 10.10.2023. Фрагменты CalculateProcess и TreatDataFromFile из архива 2022 года сопоставляются с этой реализацией отдельно. Полная старая сборка, перенос архивного алгоритма и диагностическое изменение современного алгоритма получают разные обозначения.')
 table(d,'Таблица 1 — Проверяемые исторические изменения',['Фактор','Версии и даты','Проверка'],[
 ('Синапсы','5f3f06d 15.04.2022; 0be546f 27.06.2022','R: 100 МОм или 1 ГОм; постоянные времени: 0,002/0,002 или 0,001/0,01 с'),
 ('Связи и порядок','1e1a1c9, 8f47c01, 805fda1','Порядок вычислений, прохождение импульса, задержки'),
 ('Выход и LTZone','ff77ca4, 7cf11a1, b99714c','Измеряемый сигнал и правило бинарного решения'),
 ('Пороги и время','59ece28','Границы итерации и переключение режимов'),
 ('Инициализация','fcaa969, aec0302; история Rdk','Активность и IsInit каждого созданного компонента'),
 ('Остановка NT','Отдельные фрагменты fcaa969','Достижимость критерия и колебания между структурами')],[3.4,5,8.1])
 heading(d,'2 Варианты кода и причинные проверки')
 paragraph(d,'V0 — исходный autoPreset предыдущей проверки. V1 — минимальное исправление инициализации без изменения условий остановки. V2 — V1 с документированными параметрами создаваемых синапсов периода апреля–июня 2022 года. V3 — восстанавливаемый архивный алгоритм с перечнем адаптаций к инфраструктуре.')
 paragraph(d,'Остановка, порядок вычислений, выходной сигнал и файловый контроллер проверяются отдельными диагностическими вариантами на пилоте. Смешанные исторические коммиты разделяются по смыслу. Для обнаруженного эффекта выполняются включение изменения, измерение и обратная проверка после его отмены. Взаимодействие факторов проверяется парным сочетанием.')
 paragraph(d,'Каждому варианту соответствуют отдельный исполняемый файл, Git-ревизии модулей, контрольные суммы источников и бинарника. Производственные интерфейсы компонентов специально для стенда не расширяются. Полные исторические версии собираются по согласованным закреплениям сабмодулей; отсутствие необходимых исходников или зависимостей документируется.')
 heading(d,'3 Матрица и порядок выполнения')
 table(d,'Таблица 2 — Последовательность серий',['Этап','Состав','Условие перехода'],[
 ('Проверка стенда','Входы, такты, итерации, наблюдатель, сохранение и загрузка; файловый и внешний контроллер','Согласованные стимулы и отсутствие вмешательства'),
 ('Пилот','NT/NL № 22, 64, 111; NL № 51, 61 и средний вход; три повтора','Корректная инициализация и измерение остановки'),
 ('Десятка','NT/NL № 22, 37, 45, 60, 64, 84, 90, 111, 129, 134','Повторное использование совпадающих пилотных случаев'),
 ('Полная матрица','NT/NL на 150 объектах; 90 переходов NL в историческом порядке; 32 случая режимов','Работоспособный основной вариант и выполненные предусловия'),
 ('Два входа','2/2, 3/4, 0/1, исправленная 0/(1+4), отдельные 51, 61 и средний вход','Документированный порядок и раздельный учёт подвыборок')],[3,8.5,5])
 paragraph(d,'В режимах 0/1 ноль означает отсутствие дополнительного обучения № 51 после первоначального обучения ему. В 0/(1+4) выполняется одна совместная итерация изменения дендритов и синапсов и четыре итерации только синапсов на № 61. Предварительная неоднозначная схема 0/(1(2)+4) не подменяется исправленной; допустимые реконструкции обозначаются явно.')
 paragraph(d,'Массовые серии не запускаются на неинициализированном графе. Неуспех начального обучения исключает запуск зависимого переобучения, но оставляет конкретную запись о невыполненном предусловии для каждого запланированного случая. Близость к архивному результату не используется для выбора варианта, расширяемого до полной матрицы.')
 heading(d,'4 Обученные состояния и сравнение инференса')
 paragraph(d,'Сохраняются фактически полученные граф и параметры. Архивные длины и числа синапсов не подставляются вместо результата обучения. После завершения состояния переводятся в отдельные копии для инференса с проверкой сохранности физических параметров и связей.')
 paragraph(d,'Влияние обучения оценивается на одном контрольном механизме инференса, соответствующем ScientificComparisons. Влияние версии инференса оценивается на одном и том же неизменном состоянии. Основной проход — непрерывный; независимый Reset перед каждым входом является отдельным контролем. Неполные источники и несовместимые форматы не дополняются молча.')
 paragraph(d,'Для одинаковых входов сохраняются бинарные ответы, TP, FP, FN, TN, precision, recall, balanced accuracy, число ошибок Q, пики, времена спайков и запас до порога. Дополнительно сравниваются структуры, траектории, число итераций и повторяемость. Использование тех же 150 объектов не трактуется как независимая оценка обобщения.')
 paragraph(d,'Подтверждение обучения требует предусмотренного протоколом завершения, корректного физического графа и воспроизводимой реакции на обучающий вход после сохранения и загрузки. Достижение лимита, фиксированное число итераций и изменённый критерий остановки учитываются раздельно. Процент сходства не является единственным критерием.')
 heading(d,'5 Условия выполнения и отчётность')
 paragraph(d,'Используется только Release со штатной рабочей папкой Bin/Platform/Win. Новые скрипты размещаются в корневом Scripts, конфигурации — в Bin/Configs/StructTrainClassic. Дополнительный worktree не создаётся. Частота расчёта 2000 Гц, стимулов 1,5 Гц; три повтора, пределы 1000 итераций и 600 секунд на попытку. Лимит означает ограниченность измерения, а не доказанную невозможность обучения.')
 paragraph(d,'После пилота оцениваются длительность и объём полной матрицы. Паспорт запуска содержит версии, правки, параметры, начальное состояние, стимулы, события изменения структуры и причину остановки. Повторные одинаковые прогоны показывают воспроизводимость исполнения, но не создают независимые наборы Iris.')
 paragraph(d,'Результаты представляются в DOCX и XLSX. DOCX включает диаграммы из XLSX, описание протоколов и анализ. Научные графики сравнивают историческое обучение, новые обученные состояния и инференс предыдущего отчёта. Оси и единицы подписываются; для редких измерений используются крупные маркеры и пунктир. Структурные различия приводятся отдельно.')
 paragraph(d,'Работа завершается, когда каждый запланированный случай имеет результат либо конкретную причину невыполнения. Объяснения получают один из статусов: подтверждено экспериментом; поддерживается ограниченными данными; гипотеза; не установлено. Отрицательные результаты сохраняются. Исходный отчёт и его данные проверяются по контрольным суммам.')
 DELIVERY.mkdir(parents=True,exist_ok=True);d.save(DELIVERY/'TrainingReproducibilityPlan.docx');print('Created DOCX research plan')
